<?php $title = 'Transaksi'; require __DIR__ . '/layout.php'; ?><section class="page-head"><div><p class="eyebrow">POINT OF SALE</p><h1>Transaksi penjualan</h1><p>Pilih barang, atur jumlah, dan selesaikan pembayaran.</p></div></section><form class="panel sale-form" method="post" action="/kelompok-5/transaksi"><div class="form-grid"><label>Kasir ID<input type="number" name="id_kasir" required></label><label>Pelanggan<select name="id_pelanggan" required><?php foreach ($customers ?? [] as $customer): ?><option value="<?= $customer['id_pelanggan'] ?>"><?= htmlspecialchars($customer['nama_pelanggan']) ?></option><?php endforeach; ?></select></label></div><div id="cart"><div class="cart-row"><select name="details[0][id_produk]" required><?php foreach ($products ?? [] as $product): ?><option value="<?= $product['id_produk'] ?>" data-price="<?= $product['harga'] ?>"><?= htmlspecialchars($product['nama_produk']) ?> (stok <?= $product['stok'] ?>)</option><?php endforeach; ?></select><input name="details[0][jumlah]" type="number" min="1" value="1" required><input name="details[0][harga]" type="number" min="0" placeholder="Harga" required></div></div><button class="button secondary" type="button" id="add-item">+ Tambah barang</button><div class="payment"><label>Pembayaran<input id="payment" name="pembayaran" type="number" min="0" required></label><div class="total-box">Total <strong id="total">Rp 0</strong></div></div><button class="button" type="submit">Simpan & cetak struk</button></form><?php require __DIR__ . '/footer.php'; ?>